     * @param recipient The address it's bridged out to on the target chain.
     * @param token The address of the ERC20 token on the target chain.
     * @param sender The address bridging out.
     * @param amount The amount bridged out.
     * @param chain The chain to which the funds are being bridged out to, for reference
     *        please see the enum on the MezoBridge contract
     *        https://github.com/thesis/mezo-portal/blob/main/solidity/contracts/MezoBridge.sol#L22-L27
     */
    event AssetsUnlocked(
        uint256 indexed unlockSequenceNumber,
        bytes indexed recipient,
        address indexed token,
        address sender,
        uint256 amount,
        uint8 chain
    );

    /**
     * @notice Emitted when the minimum bridge-out amount for a token is updated.
     * @param mezoToken The address of the token on the Mezo chain.
     * @param minAmount The new minimum bridgeable amount for this token.
     */
    event MinBridgeOutAmountSet(
        address indexed mezoToken,
        uint256 minAmount
    );

    /**
     * @notice Emitted when the minimum bridge-out amount for the Bitcoin chain is updated.
     * @param minAmount The new minimum bridgeable amount for the Bitcoin chain.
     */
    event MinBridgeOutAmountForBitcoinChainSet(
        uint256 minAmount
    );

    /**
     * @notice Emitted when a target chain is removed from the set of chains
     *         enabled for bridge-outs.
     * @param chain The removed target chain, 0 for Ethereum, 1 for Bitcoin.
     */
    event BridgeOutChainRemoved(
        uint8 chain
    );

    /**
     * @notice Emitted when a target chain is added to the set of chains
     *         enabled for bridge-outs.
     * @param chain The added target chain, 0 for Ethereum, 1 for Bitcoin.
     */
    event BridgeOutChainAdded(
        uint8 chain
    );

    /**
     * @notice Emitted when a triparty bridge request is made.
     * @param requestId The unique identifier of the bridge request.
     * @param recipient The address to receive the minted BTC.
     * @param amount The amount of BTC requested.
     * @param controller The triparty controller that made the request.
     */
    event TripartyBridgeRequested(
        uint256 indexed requestId,
        address indexed recipient,
        uint256 amount,
        address controller
    );

    /**
     * @notice Emitted when a triparty controller is allowed or disallowed.
     * @param controller The address of the triparty controller.
     * @param isAllowed Whether the controller is allowed.
     */
    event TripartyControllerAllowed(
        address indexed controller,
        bool isAllowed
    );

    /**
     * @notice Helper function used to enable bridged assets observability.
     */
    function bridge(AssetsLocked[] memory events) external returns (bool);

    /**
     * @notice Creates a new ERC20 token mapping.
     * @param sourceToken The address of the ERC20 token on the source chain.
     * @param mezoToken The address of the ERC20 token on the Mezo chain.
     * @dev Requirements:
     *      - The caller must be the contract owner,
     *      - The sourceToken address must not be the zero address,
     *      - The mezoToken address must not be the zero address,
     *      - The sourceToken address must not be already mapped,
     *      - The maximum number of mappings (getMaxERC20TokensMappings) must not be reached.
     */
    function createERC20TokenMapping(address sourceToken, address mezoToken) external returns (bool);

    /**
     * @notice Deletes an existing ERC20 token mapping.
     * @param sourceToken The address of the ERC20 token on the source chain.
     * @dev Requirements:
     *      - The caller must be the contract owner,
     *      - The source token address must correspond to an existing mapping.
     */
    function deleteERC20TokenMapping(address sourceToken) external returns (bool);

    /**
     * @notice Returns the ERC20 token mapping by source token address.
     * @param sourceToken The address of the ERC20 token on the source chain.
     * @return The ERC20 token mapping. If the source token is not mapped,
     *         the mapping will have both token addresses set to the zero address.
     */
    function getERC20TokenMapping(address sourceToken) external view returns (ERC20TokenMapping memory);

    /**
     * @notice Returns the list of all ERC20 token mappings supported by the bridge.
     * @return The list of ERC20 token mappings.
     */
    function getERC20TokensMappings() external view returns (ERC20TokenMapping[] memory);

    /**
     * @notice Returns the maximum number of ERC20 token mappings supported by the bridge.
     * @return The maximum number of ERC20 token mappings.
     */
    function getMaxERC20TokensMappings() external view returns (uint256);

    /**
     * @notice Returns the address of the BTC token on the source chain.
     * @dev AssetsLocked events carrying this token address are directly mapped
     *      to the Mezo native denomination - BTC.
     */
    function getSourceBTCToken() external view returns (address);

    /**
     * @notice Returns the current assets locked sequence tip of the bridge.
     * @return The current assets locked sequence tip of the bridge.
     */
    function getCurrentSequenceTip() external view returns (uint256);

    /**
     * @notice Initiates the bridge out process by unlocking the given assets on Mezo.
     * @param token The address of the ERC20 token on Mezo.
     * @param amount The amount of the ERC20 token to unlock, in the token-specific precision.
     * @param chain The target chain to bridge out to, 0 for Ethereum, 1 for Bitcoin.
     * @param recipient The target address to send the funds to.
              - On Ethereum: recipient is a 20-byte EVM address
              - On Bitcoin: recipient is a proper standard-type Bitcoin script
                supported by tBTC, i.e. P2PKH, P2WPKH, P2SH or P2WSH
     * @return True if the call succeeded, false otherwise.
     */
    function bridgeOut(address token, uint256 amount, uint8 chain, bytes calldata recipient) external returns (bool);

    /**
     * @notice Sets the outflow limit for a specific token.
     * @param token The address of the token to set the limit for.
     * @param limit The maximum amount that can be bridged out in a 25,000 block window,
     *              in the token-specific precision.
     * @dev Requirements:
     *      - The caller must be the PoA owner.
     * @return True if the call succeeded, false otherwise.
     */
    function setOutflowLimit(address token, uint256 limit) external returns (bool);

    /**
     * @notice Gets the current outflow limit for a specific token.
     * @param token The address of the token to check the limit for.
     * @return The current outflow limit for the token, in the token-specific precision.
     */
    function getOutflowLimit(address token) external view returns (uint256);

    /**
     * @notice Gets the outflow capacity for a specific token.
     * @param token The address of the token to check the capacity for.
     * @return capacity The remaining outflow capacity for the token (outflow limit - current outflow),
     *                         in the token-specific precision.
     * @return resetHeight The block height when the capacity will reset (last outflow reset + reset blocks).
     */
    function getOutflowCapacity(address token) external view returns (uint256 capacity, uint256 resetHeight);

    /**
     * @notice Sets the minimum bridge-out amount for the given token.
     * @param mezoToken The address of the token on the Mezo chain.
     * @param minAmount The new minimum amount for the given token.
     * @dev Requirements:
     *      - The caller must be the contract owner,
     *      - The mezoToken address must not be the zero address,
     *      - The minAmount must be positive.
     */
    function setMinBridgeOutAmount(address mezoToken, uint256 minAmount) external returns (bool);

    /**
    * @notice Returns the minimum bridge-out amount (if set) for a Mezo token.
    * @param mezoToken The address of the token on the Mezo chain.
    * @return The current minimum amount for the token (0 if unset).
    * @dev For bridge outs to the Bitcoin chain, the system will always check
    *      the Bitcoin-specific minimum returned by getMinBridgeOutAmountForBitcoinChain
    *      first, and fallback to the value returned by this function if the
    *      Bitcoin-specific value is zero.
    */
    function getMinBridgeOutAmount(address mezoToken) external view returns (uint256);

    /**
     * @notice Sets the minimum amount for bridging out to the Bitcoin chain.
     * @param minAmount The new minimum amount.
     * @dev Requirements:
     *      - The caller must be the contract owner,
     *      - The minAmount must be zero or positive.
     * @dev This function is here to address the specific case of bridging out to the Bitcoin chain,
     *      that relies on the tBTC bridge under the hood. As the tBTC bridge has its own minimum
     *      amount, we need to distinguish between the minimum BTC bridge-out targeting the
     *      Ethereum chain (not depending on the tBTC bridge) and the minimum BTC bridge-out
     *      targeting the Bitcoin chain (depending on the tBTC bridge). In practice, this
     *      value should be always equal (or greater than) the redemptionDustThreshold
     *      parameter returned by the redemptionParameters function of the tBTC Bridge contract.
     */
    function setMinBridgeOutAmountForBitcoinChain(uint256 minAmount) external returns (bool);

    /**
    * @notice Returns the minimum amount for bridging out to the Bitcoin chain.
    * @return The current minimum amount (0 if unset).
    * @dev For backward compatibility, if the minimum amount for the Bitcoin chain is not set
    *      (i.e. this function returns zero), the system will try to use the value returned
    *      by getMinBridgeOutAmount for the BTC token.
    */
    function getMinBridgeOutAmountForBitcoinChain() external view returns (uint256);

    /**
     * @notice Removes a target chain from the set of chains enabled for
     *         bridge-outs. Bridge-outs to a removed chain are rejected.
     * @param chain The target chain, 0 for Ethereum, 1 for Bitcoin.
     * @dev Requirements:
     *      - The caller must be the contract owner,
     *      - The chain must be a supported target chain,
     *      - The chain must be enabled for bridge-outs.
     * @return True if the call succeeded, false otherwise.
     */
    function removeBridgeOutChain(uint8 chain) external returns (bool);

    /**
     * @notice Adds a target chain to the set of chains enabled for bridge-outs.
     * @param chain The target chain, 0 for Ethereum, 1 for Bitcoin.
     * @dev Requirements:
     *      - The caller must be the contract owner,
     *      - The chain must be a supported target chain,
     *      - The chain must not be enabled for bridge-outs yet.
     * @return True if the call succeeded, false otherwise.
     */
    function addBridgeOutChain(uint8 chain) external returns (bool);

    /**
     * @notice Returns the set of target chains enabled for bridge-outs.
     * @return The enabled target chains in ascending order, 0 for Ethereum,
     *         1 for Bitcoin. An empty list means all bridge-outs are disabled.
     */
    function getBridgeOutChains() external view returns (uint8[] memory);

    /**
     * @notice Requests a triparty BTC mint through the bridge.
     * @param recipient The address to receive the minted BTC.
     * @param amount The amount of BTC to mint in 1e18 precision.
     * @param callbackData Arbitrary data passed to the callback on completion.
     * @return requestId The unique identifier of the bridge request.
     * @dev Requirements:
     *      - Triparty bridging must not be paused,
     *      - The caller must be an allowed triparty controller,
     *      - The recipient address must not be the zero address,
     *      - The amount must be positive,
     *      - The amount must be at least 0.01 BTC,
     *      - The amount must not exceed the per-request limit,
     *      - The amount must not exceed the remaining triparty request window capacity,
     *      - The callbackData must not exceed 320 bytes.
     */
    function bridgeTriparty(address recipient, uint256 amount, bytes calldata callbackData) external returns (uint256 requestId);

    /**
     * @notice Allows or disallows a triparty controller address.
     * @param controller The address of the triparty controller.
     * @param isAllowed Whether the controller should be allowed.
     * @dev Requirements:
     *      - The caller must be the PoA owner,
     *      - The controller address must not be the zero address.
     */
    function allowTripartyController(address controller, bool isAllowed) external returns (bool);

    /**
     * @notice Checks if an address is an allowed triparty controller.
     * @param controller The address to check.
     * @return True if the address is an allowed triparty controller.
     */
    function isAllowedTripartyController(address controller) external view returns (bool);

    /**
     * @notice Emitted when the triparty block delay is updated.
     * @param delay The new block delay value.
     */
    event TripartyBlockDelaySet(uint256 delay);

    /**
     * @notice Sets the number of blocks that must pass between a triparty
     *         mint request and its execution by the PreBlocker.
     * @param delay The block delay. Must be at least 1.
     * @dev Requirements:
     *      - The caller must be the PoA owner,
     *      - The delay must be at least 1.
     */
    function setTripartyBlockDelay(uint256 delay) external returns (bool);

    /**
     * @notice Returns the number of blocks that must pass between a triparty
     *         mint request and its execution by the PreBlocker.
     * @return delay The current block delay value.
     */
    function getTripartyBlockDelay() external view returns (uint256 delay);

    /**
     * @notice Emitted when the triparty limits are updated.
     * @param perRequestLimit The new per-request limit.
     * @param windowLimit The new window limit.
     */
    event TripartyLimitsSet(uint256 perRequestLimit, uint256 windowLimit);

    /**
     * @notice Sets the global triparty request limits shared by all controllers.
     * @param perRequestLimit The maximum amount that can be requested in a single request.
     * @param windowLimit The maximum amount that can be requested in a single window.
     * @dev Requirements:
     *      - The caller must be the PoA owner,
     *      - Both limits must be non-negative.
     */
    function setTripartyLimits(
        uint256 perRequestLimit,
        uint256 windowLimit
    ) external returns (bool);

    /**
     * @notice Returns the configured triparty request limits.
     * @return perRequestLimit The maximum amount that can be requested in a single request.
     * @return windowLimit The maximum amount that can be requested in a single window.
     */
    function getTripartyLimits() external view returns (uint256 perRequestLimit, uint256 windowLimit);

    /**
     * @notice Returns the remaining triparty request window capacity within the
     *         current window and the block height at which it resets.
     * @return capacity The remaining triparty request window capacity in the current window.
     * @return resetHeight The block height when the window resets.
     */
    function getTripartyCapacity() external view returns (uint256 capacity, uint256 resetHeight);

    /**
     * @notice Returns the total BTC minted via the triparty bridge path.
     *         This is an informational provenance counter.
     * @return totalMinted The cumulative amount of BTC minted through triparty.
     */
    function getTripartyTotalBTCMinted() external view returns (uint256 totalMinted);

    /**
     * @notice Returns the BTC minted via the triparty bridge path by a
     *         specific controller. This is an informational provenance counter.
     * @param controller The address of the triparty controller.
     * @return minted The cumulative amount of BTC minted by this controller
     *         through triparty.
     */
    function getTripartyControllerBTCMinted(address controller) external view returns (uint256 minted);

    /**
     * @notice Returns the last assigned triparty request sequence number.
     *         This is the total number of triparty bridge requests submitted.
     * @return sequenceTip The last assigned request sequence number.
     */
    function getTripartyRequestSequenceTip() external view returns (uint256 sequenceTip);

    /**
     * @notice Returns the last processed triparty request sequence number.
     *         Together with getTripartyRequestSequenceTip, callers can derive
     *         the number of pending requests (requestTip - processedTip).
     * @return sequenceTip The last processed request sequence number.
     */
    function getTripartyProcessedSequenceTip() external view returns (uint256 sequenceTip);
}

package assetsbridge

import (
	"bytes"
	"encoding/hex"
	"errors"
	"fmt"
	"math/big"

	"github.com/btcsuite/btcd/txscript"
	"github.com/btcsuite/btcd/wire"
	sdk "github.com/cosmos/cosmos-sdk/types"
	banktypes "github.com/cosmos/cosmos-sdk/x/bank/types"
	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/core/tracing"
	"github.com/holiman/uint256"
	"github.com/mezo-org/mezod/precompile"
	"github.com/mezo-org/mezod/x/evm/statedb"
	evmtypes "github.com/mezo-org/mezod/x/evm/types"
)

// BridgeOutMethodName is the name of the bridgeOut method.
// It matches the name of the method in the contract ABI.
//
//nolint:gosec
const BridgeOutMethodName = "bridgeOut"

// SendMsgURL defines the authorization type for MsgSend
var SendMsgURL = sdk.MsgTypeURL(&banktypes.MsgSend{})

// BridgeOutMethod is the implementation of the bridgeOut method.
type BridgeOutMethod struct {
	bridgeKeeper BridgeKeeper
	authzKeeper  AuthzKeeper
}

func newBridgeOutMethod(
	bridgeKeeper BridgeKeeper,
	authzKeeper AuthzKeeper,
) *BridgeOutMethod {
	return &BridgeOutMethod{
		bridgeKeeper: bridgeKeeper,
		authzKeeper:  authzKeeper,
	}
}

func (m *BridgeOutMethod) MethodName() string {
	return BridgeOutMethodName
}

func (m *BridgeOutMethod) MethodType() precompile.MethodType {
	return precompile.Write
}

func (m *BridgeOutMethod) RequiredGas(_ []byte) (uint64, bool) {
	// Fallback to the default gas calculation.
	return 0, false
}

func (m *BridgeOutMethod) Payable() bool {
	return false
}

func (m *BridgeOutMethod) Run(
	context *precompile.RunContext,
	rawInputs precompile.MethodInputs,
) (precompile.MethodOutputs, []statedb.StateChange, error) {
	inputs, err := m.extractInputs(rawInputs)
	if err != nil {
		return precompile.MethodOutputs{false}, nil, err
	}

	if err := m.validate(context, inputs); err != nil {
		return precompile.MethodOutputs{false}, nil, err
	}

	return m.execute(context, inputs)
}

// execute will execute the burn of the token then send
// AssetsUnlocked events to the bridgeKeeper.
func (m *BridgeOutMethod) execute(
	context *precompile.RunContext,
	inputs *bridgeOutInputs,
) (precompile.MethodOutputs, []statedb.StateChange, error) {
	var (
		err   error
		isBTC = bytes.Equal(
			common.HexToAddress(evmtypes.BTCTokenPrecompileAddress).Bytes(),
			inputs.Token.Bytes(),
		)
	)

	sdkAmount, err := precompile.TypesConverter.BigInt.ToSDK(inputs.Amount)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to convert amount: [%w]", err)
	}
	assetsUnlocked, err := m.bridgeKeeper.SaveAssetsUnlocked(
		context.SdkCtx(),
		inputs.Recipient,
		inputs.Token.Bytes(),
		context.MsgSender().Bytes(),
		sdkAmount,
		uint8(inputs.Chain),
	)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to send AssetsUnlocked to bridge: %w", err)
	}

	err = context.EventEmitter().Emit(
		NewAssetsUnlockedEvent(
			assetsUnlocked.UnlockSequence.BigInt(),
			assetsUnlocked.Recipient,
			common.HexToAddress(assetsUnlocked.Token),
			context.MsgSender(),
			assetsUnlocked.Amount.BigInt(),
			uint8(assetsUnlocked.Chain), //nolint:gosec // G115: Safe conversion, Chain is validated elsewhere
		),
	)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to emit AssetsUnlocked event: [%w]", err)
	}

	var changes []statedb.StateChange

	switch inputs.Chain {
	case TargetChainEthereum:
		if isBTC {
			err = m.burnBitcoin(context, inputs)
		} else {
			changes, err = m.burnERC20(context, inputs)
		}
	case TargetChainBitcoin:
		err = m.burnBitcoin(context, inputs)
	default:
		panic(fmt.Sprintf("unreachable, unsupported target chain: %v", inputs.Chain))
	}

	return precompile.MethodOutputs{err == nil}, changes, err
}

func (m *BridgeOutMethod) burnERC20(
	context *precompile.RunContext,
	inputs *bridgeOutInputs,
) ([]statedb.StateChange, error) {
	var (
		sdkCtx   = context.SdkCtx()
		fromAddr = context.MsgSender()
	)

	return m.bridgeKeeper.BurnERC20(
		sdkCtx, inputs.Token.Bytes(), fromAddr.Bytes(), inputs.Amount)
}

func (m *BridgeOutMethod) burnBitcoin(
	context *precompile.RunContext,
	inputs *bridgeOutInputs,
) error {
	bridgeAddr := sdk.AccAddress(common.HexToAddress(
		evmtypes.AssetsBridgePrecompileAddress,
	).Bytes())
	senderAddr := sdk.AccAddress(context.MsgSender().Bytes())

	authorization, expiration := m.authzKeeper.GetAuthorization(
		context.SdkCtx(), bridgeAddr.Bytes(), senderAddr.Bytes(), SendMsgURL,
	)
	if authorization == nil {
		return fmt.Errorf("%s authorization type does not exist or is expired for address %s", SendMsgURL, senderAddr)
	}

	sendAuth, ok := authorization.(*banktypes.SendAuthorization)
	if !ok {
		return fmt.Errorf(
			"expected authorization to be a %T", banktypes.SendAuthorization{},
		)
	}

	sdkAmount, err := precompile.TypesConverter.BigInt.ToSDK(inputs.Amount)
	if err != nil {
		return fmt.Errorf("failed to convert amount: [%w]", err)
	}
	coin := sdk.Coin{Denom: evmtypes.DefaultEVMDenom, Amount: sdkAmount}

	// now update the authorization to spend for the AssetsBridge
	msg := banktypes.NewMsgSend(senderAddr.Bytes(), bridgeAddr.Bytes(), sdk.NewCoins(coin))
	resp, err := sendAuth.Accept(context.SdkCtx(), msg)
	if err != nil {
		return fmt.Errorf("couldn't accept authorization: %w", err)
	}

	if resp.Delete {
		// Authorization fully consumed, delete it
		err = m.authzKeeper.DeleteGrant(context.SdkCtx(), bridgeAddr, senderAddr, SendMsgURL)
	} else if resp.Updated != nil {
		err = m.authzKeeper.SaveGrant(context.SdkCtx(), bridgeAddr, senderAddr, resp.Updated, expiration)
	}
	if err != nil {
		return fmt.Errorf("couldn't update authorization BTC: %w", err)
	}

	if !resp.Accept {
		return errors.New("bridge is not authorized to burn BTC")
	}

	if err := m.bridgeKeeper.BurnBTC(
		context.SdkCtx(),
		senderAddr.Bytes(),
		sdkAmount,
	); err != nil {
		return fmt.Errorf("couldn't burn BTC: %w", err)
	}

	// finally update the journal entries to propagate the changes
	// done to the gas token (BTC in our case)
	balanceDelta, overflow := uint256.FromBig(inputs.Amount)
	if overflow {
		return fmt.Errorf("conversion from big.Int to uint256.Int overflowed: %v", inputs.Amount)
	}

	// only one side of the transfer to update here as we
	// burnt funds
	journal := context.Journal()
	journal.SubBalance(common.BytesToAddress(senderAddr.Bytes()), balanceDelta, tracing.BalanceChangeTransfer)

	return nil
}

// validate applies more extensive validation to the inputs, not only
// the semantic validation but also verify balances, and tokens etc.
func (m *BridgeOutMethod) validate(
	context *precompile.RunContext,
	inputs *bridgeOutInputs,
) error {
	sdkCtx := context.SdkCtx()

	if inputs.Amount == nil {
		return errors.New("amount is required")
	}

	if inputs.Amount.Sign() <= 0 {
		return errors.New("amount must be positive")
	}

	if err := m.validateAmount(sdkCtx, inputs.Amount, inputs.Token, inputs.Chain); err != nil {
		return err
	}

	_, ok := inputs.Chain.Validate()
	if !ok {
		return fmt.Errorf("unsupported chain: %v", inputs.Chain)
	}

	if err := m.validateRecipientForChain(inputs.Chain, inputs.Recipient); err != nil {
		return err
	}

	// first check that the token is either BTC or a supported ERC20
	if err := m.validateToken(sdkCtx, inputs.Token, inputs.Chain); err != nil {
		return err
	}

	return nil
}

func (m *BridgeOutMethod) validateToken(
	sdkCtx sdk.Context,
	token common.Address,
	chain TargetChain,
) error {
	btcToken := common.HexToAddress(evmtypes.BTCTokenPrecompileAddress)
	if bytes.Equal(btcToken.Bytes(), token.Bytes()) {
		return nil
	}

	switch chain {
	case TargetChainEthereum:
		if _, ok := m.bridgeKeeper.GetERC20TokenMappingFromMezoToken(sdkCtx, token.Bytes()); ok {
			return nil
		}

		return fmt.Errorf("unsupported token: %v for ethereum target chain", token)
	case TargetChainBitcoin:
		return fmt.Errorf("unsupported token: %v for bitcoin target chain", token)
	default:
		panic("unreachable: unknown chain type")
	}
}

func (m *BridgeOutMethod) validateAmount(
	sdkCtx sdk.Context,
	amount *big.Int,
	token common.Address,
	chain TargetChain,
) error {
	sdkAmount, err := precompile.TypesConverter.BigInt.ToSDK(amount)
	if err != nil {
		return fmt.Errorf("failed to convert amount: [%w]", err)
	}

	if chain == TargetChainBitcoin {
		// For Bitcoin chain, first check Bitcoin-specific minimum. If it is not set,
		// use the general minimum.
		bitcoinMinAmount := m.bridgeKeeper.GetMinBridgeOutAmountForBitcoinChain(sdkCtx)
		if !bitcoinMinAmount.IsZero() {
			if sdkAmount.LT(bitcoinMinAmount) {
				return fmt.Errorf(
					"amount below minimum bridgeable amount for Bitcoin chain: %s < %s",
					sdkAmount,
					bitcoinMinAmount,
				)
			}
			// Bitcoin-specific minimum is set and respected, we should not check the general minimum
			// so we return here.
			return nil
		}
	}

	minAmount := m.bridgeKeeper.GetMinBridgeOutAmount(
		sdkCtx,
		token.Bytes(),
	)

	if sdkAmount.LT(minAmount) {
		return fmt.Errorf(
			"amount below minimum bridgeable amount: %s < %s",
			sdkAmount,
			minAmount,
		)
	}

	return nil
}

// extractInputs extract the inputs from the precompile.MethodInputs and apply
// basic validation on the inputs
func (m *BridgeOutMethod) extractInputs(inputs precompile.MethodInputs) (*bridgeOutInputs, error) {
	if err := precompile.ValidateMethodInputsCount(inputs, 4); err != nil {
		return nil, err
	}

	token, ok := inputs[0].(common.Address)
	if !ok {
		return nil, fmt.Errorf("invalid token address: %v", inputs[0])
	}

	amount, ok := inputs[1].(*big.Int)
	if !ok {
		return nil, fmt.Errorf("invalid amount: %v", inputs[1])
	}

	chainRaw, ok := inputs[2].(uint8)
	if !ok {
		return nil, fmt.Errorf("invalid chain: %v", inputs[2])
	}

	chain := TargetChain(chainRaw)

	recipient, ok := inputs[3].([]byte)
	if !ok {
		return nil, fmt.Errorf("invalid recipient address: %v", inputs[3])
	}

	return &bridgeOutInputs{
		Token:     token,
		Amount:    amount,
		Chain:     chain,
		Recipient: recipient,
	}, nil
}

func (m *BridgeOutMethod) validateRecipientForChain(chain TargetChain, recipient []byte) error {
	if len(recipient) == 0 {
		return fmt.Errorf("recipient can't be empty")
	}

	switch chain {
	case TargetChainEthereum:
		// check the length and for the zero address
		if len(recipient) != 20 || bytes.Equal(recipient, (common.Address{}).Bytes()) {
			return fmt.Errorf("invalid recipient address for Ethereum chain: %v", hex.EncodeToString(recipient))
		}
	case TargetChainBitcoin:
		script, err := newScriptFromVarLenData(recipient)
		if err != nil {
			return fmt.Errorf("couldn't get script from var-len data: %v", err)
		}
		if !isSupportedBitcoinScriptType(script) {
			return fmt.Errorf("invalid recipient address for Bitcoin: %v", hex.EncodeToString(recipient))
		}
	}

	return nil
}

type TargetChain uint8

